using System;using System.IO;using System.Text;using System.Web.Script.Serialization;using System.Collections.Generic;using ProjectGreed.Client;
class ArchiveChecks{
 static JavaScriptSerializer j=new JavaScriptSerializer();static void Check(bool b,string m){if(!b)throw new Exception(m);}
 static Dictionary<string,object> Call(NativeStore s,object q){return j.Deserialize<Dictionary<string,object>>(s.Archive(j.Serialize(q)));}
 static Dictionary<string,object> Write(NativeStore s,string id,long offset,byte[] data){return Call(s,new{op="write",id,kind="log",offset,data=Convert.ToBase64String(data),meta=new{matchId="match",count=1,title="Unicode"}});}
 static void Main(string[]args){var dir=args[0];Directory.CreateDirectory(dir);var s=new NativeStore(dir);var first=Encoding.UTF8.GetBytes("驾驶员😀\n");Check((bool)Write(s,"record_team0_log",0,first)["ok"],"first write");Check(!(bool)Write(s,"record_team0_log",0,first)["ok"],"stale offset rejected");var file=Path.Combine(dir,"records","record_team0_log.log.txt");using(var held=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.Read)){Check(!(bool)Write(s,"record_team0_log",first.Length,first)["ok"],"locked file rejected");}s=new NativeStore(dir);Check((bool)Write(s,"record_team0_log",first.Length,first)["ok"],"restart appends");Check(File.ReadAllText(file,Encoding.UTF8)=="驾驶员😀\n驾驶员😀\n","Unicode survives");Check(!(bool)Write(s,"../profile",0,first)["ok"],"traversal rejected");File.AppendAllText(file,"uncommitted",Encoding.UTF8);Check((bool)Write(s,"record_team0_log",first.Length*2,new byte[]{65})["ok"],"recover tail");Check(new FileInfo(file).Length==first.Length*2+1,"tail truncated");Check((bool)Call(s,new{op="remove",id="record_team0_log",kind="log"})["ok"],"prune file");Console.WriteLine("Archive checks passed: restart, UTF8, stale offsets, file locks, path validation, crash tail recovery, remove");}
}
